def deep_find_pairwise(obj, path=""):
    """Find ALL pairwise AUC values, handling nested structures."""
    results = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            # Direct match: key is "0v1", "1v2", etc.
            m = re.match(r'^(\d+v\d+)$', k)
            if m:
                pair = m.group(1)
                if isinstance(v, (int, float)):
                    results[pair] = v
                elif isinstance(v, dict):
                    # e.g. {"auc_point": 0.98, "ci_lower": ...}
                    if 'auc_point' in v:
                        results[pair] = v['auc_point']
                    elif 'mean' in v:
                        results[pair] = v['mean']
                    elif 'auc' in v:
                        results[pair] = v['auc']
                    elif 'mean_auc' in v:
                        results[pair] = v['mean_auc']

            # Match: key is "auc_0v1", "auc_1v2", etc.
            m2 = re.match(r'^auc_(\d+v\d+)$', k)
            if m2:
                pair = m2.group(1)
                if isinstance(v, (int, float)):
                    results[pair] = v

            # Match: key is "pairwise_auc" containing sub-dict
            if k == 'pairwise_auc' and isinstance(v, dict):
                for pk, pv in v.items():
                    pm = re.match(r'^(\d+v\d+)$', pk)
                    if pm and isinstance(pv, (int, float)):
                        results[pm.group(1)] = pv

            # Match: key is "pairs" containing sub-dict with AUC data
            if k == 'pairs' and isinstance(v, dict):
                for pk, pv in v.items():
                    pm = re.match(r'^(\d+v\d+)$', pk)
                    if pm and isinstance(pv, dict):
                        if 'auc_point' in pv:
                            results[pm.group(1)] = pv['auc_point']
                        elif 'mean_auc' in pv:
                            results[pm.group(1)] = pv['mean_auc']
                        elif 'auc' in pv:
                            results[pm.group(1)] = pv['auc']

            # Recurse into sub-dicts
            sub = deep_find_pairwise(v, f"{path}.{k}")
            # Don't overwrite with deeper values if we already have them
            for sk, sv in sub.items():
                if sk not in results:
                    results[sk] = sv
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            sub = deep_find_pairwise(item, f"{path}[{i}]")
            for sk, sv in sub.items():
                if sk not in results:
                    results[sk] = sv
    return results


def infer_metadata(exp_id, exp):
    """Extract model, domain, scorer from spec, hypothesis, and exp_id."""
    spec = exp.get('spec', {})
    model = spec.get('model_name', spec.get('model', ''))
    domain = spec.get('domain', '')
    scorer = spec.get('scorer', spec.get('scorer_model', ''))
    hyp = exp.get('hypothesis', '')
    conclusion = exp.get('conclusion', '')

    # Infer domain from exp_id or hypothesis
    if not domain:
        if 'arxiv' in exp_id.lower() or 'arxiv' in hyp.lower():
            domain = 'arxiv'
        elif 'wiki' in exp_id.lower() or 'wiki' in hyp.lower():
            domain = 'wiki'
        elif 'c4' in exp_id.lower() or 'C4' in hyp or 'c4' in hyp.lower():
            domain = 'c4'
        else:
            # Check spec for hints
            spec_str = json.dumps(spec)
            if 'c4' in spec_str.lower():
                domain = 'c4'
            elif 'arxiv' in spec_str.lower():
                domain = 'arxiv'
            elif 'wiki' in spec_str.lower():
                domain = 'wiki'

    # Infer scorer type
    scorer_type = ''
    if 'cross' in exp_id.lower() or 'cross' in scorer.lower():
        scorer_type = 'cross-scorer'
    elif scorer:
        # Check if scorer is same model family as generator
        scorer_type = 'self-scorer' if not ('cross' in exp_id.lower()) else 'cross-scorer'

    return {
        'model': model,
        'domain': domain,
        'scorer': scorer,
        'scorer_type': scorer_type,
        'hypothesis': hyp[:300] if hyp else '',
        'conclusion': conclusion,
        'status': exp.get('status', ''),
    }


# Now process ALL experiments
all_results = []
for exp_id in sorted(exps.keys()):
    exp = exps[exp_id]
    aucs = deep_find_pairwise(exp)

    if not aucs:
        continue

    meta = infer_metadata(exp_id, exp)
    pairs_sorted = sorted(aucs.items(), key=lambda x: (len(x[0]), x[0]))

    all_results.append({
        'exp_id': exp_id,
        'model': meta['model'],
        'domain': meta['domain'],
        'scorer': meta['scorer'],
        'scorer_type': meta['scorer_type'],
        'hypothesis': meta['hypothesis'],
        'conclusion': meta['conclusion'],
        'status': meta['status'],
        'pairwise_aucs': dict(pairs_sorted),
    })

print(f"Total experiments with pairwise AUC data: {len(all_results)}")
print("=" * 80)

for r in all_results:
    print(f"\n{'='*80}")
    print(f"EXP: {r['exp_id']}")
    print(f"  Status:      {r['status']}")
    print(f"  Model:       {r['model']}")
    print(f"  Domain:      {r['domain']}")
    print(f"  Scorer:      {r['scorer']}")
    print(f"  Scorer type: {r['scorer_type']}")
    print(f"  Conclusion:  {r['conclusion']}")
    print(f"  Pairwise AUCs:")
    for pair, val in sorted(r['pairwise_aucs'].items()):
        print(f"    {pair}: {val}")
    if r['hypothesis']:
        print(f"  Hypothesis:  {r['hypothesis'][:200]}")

